  [469183] = { "召喚したトーテムが、それぞれの属性の恩恵を与えます。", "召喚されたトーテムがそれぞれの属性の恩恵を与えます。", 0x5d8a8187, 0x5d8a8187, "uu" },
  [469191] = { "書物の予言を読み上げ、次に使う周期的でない呪文または攻撃のクリティカル率を$N1%上昇させます。", "次の呪文または攻撃のクリティカル率が$N1%上昇します。", 0x6ba2ca42, 0x1318f7a9, "uu" },
  [469199] = { "Terrestrisの炎を冷まし、防御のために硬化させます。", nil, 0x83d2f7bf, nil, "um" },
  [469201] = { "Terrestrisの炎を燃え上がらせ、攻撃のために熱します。", nil, 0xcf4f762c, nil, "um" },
  [469208] = { "クリティカル効果の確率が$N1%上昇しています。", "クリティカル効果の発生率が$N1%上昇します。", 0xa0324ada, 0xa0324ada, "uu" },
  [469209] = { "呪文ダメージが最大$N1増加しています。", "呪文のダメージが最大$N1増加します。", 0x9d292bc3, 0x9d292bc3, "uu" },
  [469210] = { "回復量が最大$N1増加しています。", "回復量が最大$N1増加します。", 0x280fa82d, 0x280fa82d, "uu" },
  [469211] = { "直接ダメージ呪文に一定の確率で、$D1以内に次に召喚するペットが即時詠唱になり、Soul Shardを消費しなくなります。", "直接ダメージ呪文に、$D1以内に次に召喚するペットを即時詠唱にし、Soul Shardを消費させない効果が発動することがあります。", 0x41f371df, 0x41f371df, "uu" },
  [469220] = { "次のImp、Voidwalker、Succubus、Incubus、Felhunter、FelguardのSummon呪文の詠唱時間が$D1短縮され、Soul Shardもマナも消費しません。", "Imp、Voidwalker、Succubus、Incubus、Fellhunter、Felguardの詠唱時間が$D1短縮されます。マナとSoul Shardのコストが$N2%減少します。", 0x59404b53, 0xbe3d1d6a, "uu" },
  [469221] = { "召喚している悪魔の魂を刈り取り、$D1持続する効果を得ます。いずれかの悪魔を召喚すると、この効果は解除されます。", nil, 0xe0855949, nil, "um" },
  [469222] = { nil, "Fireダメージが$N1%増加します。", nil, 0x943a352e, "mu" },
  [469223] = { "すべての魔法の呪文と効果による回復量を最大$N1、ダメージを最大$N2増加させます。", nil, 0x77ff472e, nil, "um" },
  [469224] = { nil, "ダメージを受けません。何か行動すると、この効果は早く終わります。", nil, 0xb38d24a6, "mu" },
  [469225] = { nil, "Shadowダメージが$N1%増加します。", nil, 0xfb0c5fb8, "mu" },
  [469227] = { nil, "沈黙させられています。", nil, 0x20816e34, "mu" },
  [469228] = { "敵を$D1の間沈黙させます。詠唱中の対象に使うと、その詠唱を打ち消し、$D2の間その系統の魔法の呪文を詠唱できなくします。", nil, 0x516ee526, nil, "um" },
  [469229] = { "次に詠唱するCurse of Tonguesは、$D1の間、対象を沈黙させます。詠唱中の対象に使うと敵の詠唱を阻止し、$D2の間、その系統の魔法の呪文を詠唱できなくします。", "次に唱えるCurse of Tonguesは、対象を$D1沈黙させます。詠唱中の対象に使うと敵の呪文を中断し、その系統の魔法の呪文を$D2唱えられなくします。", 0xa45b705c, 0xa45b705c, "uu" },
  [469230] = { "受けるPhysicalダメージが$N1%減少し、Demon Chargeを戦闘中にも使えるようになり、クールダウンがなくなります。", "受けるPhysicalダメージが$N1%減少し、Demon Chargeが戦闘中でも使えるようになり、クールダウンもなくなります。", 0x606cad2e, 0x606cad2e, "uu" },
  [469236] = { "対象に秘術ダメージを与えるたびに、Presence of Mindの残りクールダウンが$N1秒短縮されます。", nil, 0x2f85cf03, nil, "um" },
  [469237] = { "Improved Scorchのタレントを習得していると、Blast Waveが命中した対象にFire Vulnerabilityのスタックも$N1付与されます。", "Improved Scorchを習得していると、Blast Waveが命中した目標にもFire Vulnerabilityが$N1スタック付与されます。", 0x51d0c21f, 0x51d0c21f, "uu" },
  [469238] = { "Ice Barrierが有効な間、Frostの呪文と効果によるダメージが最大$N1増加します。", "Ice Barrierが有効な間、Frost呪文と効果によるダメージが最大$N1増加します。", 0x5320a64c, 0x5320a64c, "uu" },
  [469239] = { nil, "Frost呪文のダメージと効果が最大$N1増加します。", nil, 0xd3159f07, "mu" },
  [469260] = { "戦闘の高揚に我を忘れ、時間とともに怒りを生み出しています。", "戦闘の高揚に我を忘れ、時間とともに怒りが溜まっていきます。", 0x3b699f12, 0x3b699f12, "uu" },
  [469261] = { nil, "その場に根を張っています。\nダメージが$N1%増加します。\nヘイストが$N2%上昇します。\n$D1ごとに最大体力の$N3%のダメージを与えます。\n死亡時、周囲の味方に$N5のダメージを与えます。", nil, 0x97892e33, "mu" },
