  [469301] = { "獣を手なずけ、仲間にし始めます。$D1の間、獣を手なずけることに集中している間はアーマーが$N1%減少します。何らかの理由で獣の注意がそれると、手なずけは失敗します。手なずけた直後の獣はとても不機嫌で忠誠心がありません。すぐにペットに餌を与えて機嫌をよくしてください。", "ペットを手なずけています。", 0x653847d0, 0xc7d3fce8, "uu" },
  [469306] = { "獣を手なずけ、仲間にし始めます。$D1の間、獣を手なずけることに集中している間はアーマーが$N1%減少します。何らかの理由で獣の注意がそれると、手なずけは失敗します。手なずけた直後の獣はとても不機嫌で忠誠心がありません。すぐにペットに餌を与えて機嫌をよくしてください。", "ペットを手なずけています。", 0x653847d0, 0xc7d3fce8, "uu" },
  [469320] = { "対象に溶岩を投げつけ、$N1のFireダメージを与えます。対象にFlame Shockがかかっている場合、Lava Burstは必ずクリティカルになります。", nil, 0x675aa74d, nil, "um" },
  [469348] = { "Disarmを受けません。", nil, 0xa67c30b0, nil, "um" },
  [469357] = { "敵が自分に近接攻撃を行うたびに（一秒に一度まで）、近くの敵を焼いて$N1のダメージを与え、受けるすべての魔法ダメージを$N2%減少させ、与えるFireダメージを$N3%増加させます。$D1持続します。", "攻撃を受けると周囲の敵を焼いて$N1のダメージを与え、受ける魔法ダメージが$N2%減少し、与えるFireダメージが$N3%増加します。", 0xfcb82619, 0x2cf4f599, "uu" },
